import React, { useState, useEffect } from 'react';
import api from '../services/api';

const FuncionarioDashboard = () => {
  const [vistaActiva, setVistaActiva] = useState('ofertas');
  const [ofertas, setOfertas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [descargando, setDescargando] = useState(false);

  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const tipoFuncionario = user.tipo_funcionario || 'regular';
  const nombreFuncionario = user.nombre || 'Funcionario';
  const apellidoFuncionario = user.apellido || '';

  useEffect(() => {
    cargarOfertasAprobadas();
  }, []);

  const cargarOfertasAprobadas = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/ofertas-funcionario/aprobadas/${tipoFuncionario}`);
      setOfertas(response.data.data || []);
    } catch (error) {
      console.error('Error cargando ofertas:', error);
      setError('Error al cargar las ofertas aprobadas');
    } finally {
      setLoading(false);
    }
  };

  const descargarExcelCompleto = async (ofertaId) => {
    try {
      setDescargando(true);
      setError('');
      
      const response = await api.get(`/ofertas/${ofertaId}/exportar-excel`, {
        responseType: 'blob'
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      
      const oferta = ofertas.find(o => o._id === ofertaId);
      const tipo = oferta?.es_campesena ? 'campesena' : 'regular';
      link.setAttribute('download', `oferta_${tipo}_${oferta?.programa_formacion?.codigo || ofertaId}.xlsx`);
      
      document.body.appendChild(link);
      link.click();
      link.remove();
      
      setSuccess('✅ Excel descargado correctamente');
      setTimeout(() => setSuccess(''), 3000);
      
    } catch (error) {
      console.error('Error descargando Excel:', error);
      setError(error.response?.data?.message || 'Error al descargar el Excel');
    } finally {
      setDescargando(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    window.location.href = '/login';
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return 'No definida';
    const date = new Date(fecha);
    return date.toLocaleDateString('es-ES', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  const calcularPorcentajeCupos = (disponibles, total) => {
    if (!total || total === 0) return 0;
    const ocupados = total - (disponibles || 0);
    return Math.round((ocupados / total) * 100);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#006c49] mx-auto mb-4"></div>
          <p className="text-[#45474c]">Cargando ofertas aprobadas...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8f9ff]">
      {/* Header */}
      <header className="fixed top-0 w-full z-50 flex justify-between items-center px-8 h-16 bg-[#006c49] text-white shadow-sm">
        <div className="flex items-center gap-4">
          {/* Logo SENA redondo */}
          <img 
            src="/logosena.png" 
            alt="Logo SENA" 
            className="h-10 w-10 rounded-full object-cover bg-white p-0.5 shadow-sm"
          />
          <div className="h-8 w-px bg-white/20"></div>
          <span className="text-lg font-bold">Centro de Gestión de Datos SENA</span>
        </div>
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-4">
            <span className="text-sm font-medium text-white/80">Funcionario</span>
            <span className="text-sm font-bold text-white">
              {nombreFuncionario} {apellidoFuncionario}
            </span>
          </div>
          {/* Botón de Cerrar Sesión ROJO */}
          <button 
            onClick={handleLogout}
            className="flex items-center gap-2 bg-red-600 hover:bg-red-700 active:scale-95 transition-all px-3 py-1.5 rounded-lg shadow-sm font-medium text-sm"
          >
            <span className="material-symbols-outlined text-base">logout</span>
            <span className="text-sm hidden sm:inline">Cerrar Sesión</span>
          </button>
        </div>
      </header>

      {/* Sidebar & Main Content */}
      <div className="flex pt-16 min-h-screen">
        {/* Sidebar - Mismo estilo que instructor/coordinador */}
        <aside className="fixed left-0 top-16 h-[calc(100vh-64px)] w-64 bg-white border-r border-[#c5c6cd] flex flex-col p-4 z-40">
          <div className="flex items-center gap-3 mb-6 p-1">
            <div className="w-10 h-10 bg-[#006c49] rounded-lg flex items-center justify-center text-white">
              <span className="material-symbols-outlined">scho</span>
            </div>
            <div>
              <h3 className="text-xl font-semibold text-[#006c49] leading-none capitalize">Funcionario</h3>
              <p className="text-xs text-[#45474c] opacity-70">SENA</p>
            </div>
          </div>

          <nav className="flex-1 space-y-1">
            <button 
              onClick={() => setVistaActiva('ofertas')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg border-l-4 transition-all ${
                vistaActiva === 'ofertas'
                  ? 'bg-[#6cf8bb]/30 text-[#006c49] font-semibold border-[#006c49]'
                  : 'text-[#45474c] hover:bg-[#e5eeff] border-transparent'
              }`}
            >
              <span className="material-symbols-outlined text-xl">assignment_turned_in</span>
              <span className="text-sm">Ofertas Aprobadas</span>
            </button>
            <button 
              onClick={() => setVistaActiva('historial')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg border-l-4 transition-all ${
                vistaActiva === 'historial'
                  ? 'bg-[#6cf8bb]/30 text-[#006c49] font-semibold border-[#006c49]'
                  : 'text-[#45474c] hover:bg-[#e5eeff] border-transparent'
              }`}
            >
              <span className="material-symbols-outlined text-xl">history</span>
              <span className="text-sm">Historial</span>
            </button>
          </nav>

          <div className="mt-auto">
            <div className="p-3 bg-[#eff4ff] rounded-xl border border-[#c5c6cd]/30 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-[#006c49]/10 flex items-center justify-center text-[#006c49]">
                <span className="material-symbols-outlined text-2xl">admin_panel_settings</span>
              </div>
              <div className="flex flex-col overflow-hidden">
                <span className="text-xs text-[#45474c] uppercase tracking-wider">Sistema Académico</span>
                <span className="text-sm font-bold text-[#0b1c30] truncate">
                  Tipo: {tipoFuncionario === 'campesena' ? 'Campesena' : 'Regular'}
                </span>
              </div>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="ml-64 flex-grow p-8 bg-[#f8f9ff]">
          {error && (
            <div className="mb-4 p-3 rounded-lg bg-[#ffdad6] text-[#93000a] flex items-center gap-2">
              <span className="material-symbols-outlined text-sm">error</span>
              <span>{error}</span>
            </div>
          )}
          {success && (
            <div className="mb-4 p-3 rounded-lg bg-[#6cf8bb]/30 text-[#005236] flex items-center gap-2">
              <span className="material-symbols-outlined text-sm">check_circle</span>
              <span>{success}</span>
            </div>
          )}

          {/* Vista de Ofertas Aprobadas */}
          {vistaActiva === 'ofertas' && (
            <>
              <header className="mb-6">
                <h1 className="text-2xl md:text-3xl font-semibold text-[#091426] flex items-center gap-2">
                  <span className="material-symbols-outlined text-3xl">assignment_turned_in</span>
                  Ofertas Aprobadas
                </h1>
                <p className="text-base text-[#45474c] mt-1">Gestión de programas de formación aprobados para ejecución inmediata.</p>
              </header>

              {ofertas.length === 0 ? (
                <div className="text-center py-16 bg-white rounded-xl border border-[#c5c6cd]">
                  <p className="text-[#45474c]">No hay ofertas aprobadas para ti</p>
                  <p className="text-sm text-[#75777d] mt-2">Espera a que el coordinador asigne ofertas</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-6">
                  {ofertas.map((oferta) => {
                    const porcentajeCupos = calcularPorcentajeCupos(oferta.cupos_disponibles, oferta.cupo_maximo);
                    const tieneFicha = !!oferta.ficha_sofia;
                    
                    return (
                      <div key={oferta._id} className={`bg-white rounded-xl border flex flex-col overflow-hidden transition-all hover:-translate-y-1 hover:shadow-md duration-200 ${tieneFicha ? 'border-[#006c49]/30' : 'border-[#c5c6cd]'}`}>
                        {/* Header */}
                        <div className={`p-4 border-b ${tieneFicha ? 'bg-[#006c49]/5 border-[#006c49]/30' : 'bg-[#eff4ff]/30 border-[#c5c6cd]'}`}>
                          {tieneFicha && (
                            <div className="float-right">
                              <span className="bg-[#006c49] text-white px-2 py-0.5 rounded-full text-[10px] font-bold tracking-widest uppercase">REGISTRADO</span>
                            </div>
                          )}
                          <div className="flex justify-between items-start mb-2">
                            <h3 className="text-lg font-semibold text-[#0b1c30] max-w-[70%]">{oferta.programa_formacion?.nombre_programa || 'Programa sin nombre'}</h3>
                            <span className={`px-2 py-0.5 text-xs font-bold rounded ${oferta.es_campesena ? 'bg-amber-600 text-white' : 'bg-[#006c49] text-white'}`}>
                              {oferta.es_campesena ? 'CAMPESENA' : 'REGULAR'}
                            </span>
                          </div>
                          <p className="text-xs font-medium text-[#006c49]">Código: {oferta.programa_formacion?.codigo}</p>
                        </div>

                        {/* Body */}
                        <div className="p-4 flex-grow space-y-3">
                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <p className="text-[10px] text-[#45474c]">Instructor</p>
                              <p className="text-sm font-semibold">{oferta.creado_por?.nombre || 'No asignado'}</p>
                            </div>
                            <div>
                              <p className="text-[10px] text-[#45474c]">Empresa Solicitante</p>
                              <p className="text-sm font-semibold">{oferta.empresa_solicitante?.nombre || 'No especificada'}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <span className="material-symbols-outlined text-sm text-[#75777d]">calendar_today</span>
                            <p className="text-xs">Inicia: {formatearFecha(oferta.fechas?.inicio)} - Finaliza: {formatearFecha(oferta.fechas?.fin)}</p>
                          </div>
                          <div className="space-y-1">
                            <div className="flex justify-between text-xs">
                              <span className="text-[#45474c]">Cupos asignados</span>
                              <span className="font-bold">{(oferta.cupo_maximo || 0) - (oferta.cupos_disponibles || 0)} / {oferta.cupo_maximo || 0}</span>
                            </div>
                            <div className="w-full h-1.5 bg-[#e5eeff] rounded-full overflow-hidden">
                              <div className="bg-[#006c49] h-full rounded-full" style={{ width: `${porcentajeCupos}%` }}></div>
                            </div>
                          </div>
                        </div>

                        {/* Footer */}
                        <div className={`p-4 border-t ${tieneFicha ? 'bg-[#006c49]/5 border-[#006c49]/30' : 'bg-white border-[#c5c6cd]'}`}>
                          {tieneFicha ? (
                            <div className="flex flex-col gap-2">
                              <div className="flex items-center gap-2 text-[#005236]">
                                <span className="material-symbols-outlined text-sm" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                                <p className="text-sm font-bold">Ficha: {oferta.ficha_sofia?.codigo}</p>
                              </div>
                              <button 
                                onClick={() => descargarExcelCompleto(oferta._id)}
                                disabled={descargando}
                                className="w-full flex items-center justify-center gap-2 bg-[#001334] text-white py-2 rounded-lg font-bold text-sm hover:opacity-90 transition-all disabled:opacity-60"
                              >
                                <span className="material-symbols-outlined text-sm">download</span>
                                {descargando ? 'Descargando...' : 'Descargar Excel'}
                              </button>
                            </div>
                          ) : (
                            <div className="space-y-2">
                              <button 
                                onClick={() => descargarExcelCompleto(oferta._id)}
                                disabled={descargando}
                                className="w-full flex items-center justify-center gap-2 bg-[#006c49] text-white py-2 rounded-lg font-bold text-sm hover:bg-[#004a2b] transition-all disabled:opacity-60"
                              >
                                <span className="material-symbols-outlined text-sm">download</span>
                                {descargando ? 'Descargando...' : 'Descargar Excel Completo'}
                              </button>
                              <p className="text-[10px] text-[#75777d] italic text-center">
                                * Descargue este Excel y úselo para crear la ficha en Sofía Plus.
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}

          {/* Vista de Historial */}
          {vistaActiva === 'historial' && (
            <>
              <header className="mb-6">
                <h1 className="text-2xl md:text-3xl font-semibold text-[#091426] flex items-center gap-2">
                  <span className="material-symbols-outlined text-3xl">history</span>
                  Historial de Fichas Creadas
                </h1>
                <p className="text-base text-[#45474c] mt-1">Registro de todas las fichas técnicas creadas desde ofertas aprobadas.</p>
              </header>

              <div className="text-center py-16 bg-white rounded-xl border border-[#c5c6cd]">
                <span className="material-symbols-outlined text-5xl text-[#75777d] mb-3">construction</span>
                <p className="text-[#45474c]">Próximamente...</p>
                <p className="text-sm text-[#75777d] mt-2">Esta funcionalidad estará disponible pronto.</p>
              </div>
            </>
          )}
        </main>
      </div>
    </div>
  );
};

export default FuncionarioDashboard;
